import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./Emergency.css";

const Emergency = () => {
  const navigate = useNavigate();

  const [contacts, setContacts] = useState([]);
  const [location, setLocation] = useState(null);
  const [riskMessage, setRiskMessage] = useState("");

  /* ===============================
     FETCH EMERGENCY CONTACTS
  =============================== */
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/contacts")
      .then((res) => setContacts(res.data))
      .catch((err) => console.error(err));
  }, []);

  /* ===============================
     DETECT LOCATION
  =============================== */
  useEffect(() => {
    if (!navigator.geolocation) {
      setLocation("Location not supported");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;

        // India approx bounds
        if (lat >= 8 && lat <= 37 && lng >= 68 && lng <= 97) {
          setLocation("India 🇮🇳");
        } else {
          setLocation("Outside India 🌍");
        }
      },
      () => setLocation("Location access denied")
    );
  }, []);

  /* ===============================
     SMART RISK DETECTION
  =============================== */
  useEffect(() => {
    const hour = new Date().getHours();
    let message = "";

    if (hour >= 22 || hour <= 5) {
      message = "⚠️ Night-time risk detected. Stay alert!";
    }

    setRiskMessage(message);
  }, []);

  /* ===============================
     HANDLE CALL + SAVE TO BACKEND
  =============================== */
  const handleCall = async (contact) => {
    try {
      let latitude = null;
      let longitude = null;

      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(async (pos) => {
          latitude = pos.coords.latitude;
          longitude = pos.coords.longitude;

          await axios.post("http://localhost:5000/api/calls", {
            contactName: contact.name,
            phoneNumber: contact.number,
            latitude,
            longitude,
          });

          window.location.href = `tel:${contact.number}`;
        });
      } else {
        await axios.post("http://localhost:5000/api/calls", {
          contactName: contact.name,
          phoneNumber: contact.number,
        });

        window.location.href = `tel:${contact.number}`;
      }
    } catch (err) {
      console.error("Error logging call", err);
    }
  };

  return (
    <div className="emergency-container">
      <h1>🚨 Emergency Contacts</h1>

      {/* ===== SMART STATUS PANEL ===== */}
      <div className="risk-card">
        <p>📍 Location: <b>{location || "Detecting..."}</b></p>
        <p>🕒 Time: <b>{new Date().toLocaleTimeString()}</b></p>

        {riskMessage && (
          <p className="risk-warning">{riskMessage}</p>
        )}
      </div>

      {/* ===== CONTACTS ===== */}
      <div className="contact-grid">
        {contacts.map((contact) => (
          <div key={contact._id} className="contact-card">
            <h3>{contact.name}</h3>
            <p>{contact.number}</p>
            <button
              className="call-btn"
              onClick={() => handleCall(contact)}
            >
              📞 Call Now
            </button>
          </div>
        ))}
      </div>

      <button className="back-btn" onClick={() => navigate("/")}>
        ⬅ Back to Home
      </button>
    </div>
  );
};

export default Emergency;
